body {
    font-family: 'Open Sans', sans-serif;
    line-height: 1.6;
    -webkit-hyphens: auto; /* For Safari */
    -ms-hyphens: auto;    /* For IE */
    hyphens: auto;        /* Standard */
    text-align: justify;  /* To demonstrate effect */
    max-width: 700px;
    margin: 0 auto;
}

html {
    lang: 'en'; /* Or appropriate language, e.g., 'de', 'fr' */
}
